//! Limits surface work inside Truck, including trimming PCurves. Limiting only
//! source edges does not bound the curves generated by robust_triangulation.
use super::*;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::{Duration, Instant};

pub(super) struct SurfaceLimit;

struct Budget {
    remaining: AtomicUsize,
    deadline: Instant,
}

#[derive(Clone)]
pub(super) struct Limited<S> {
    surface: S,
    budget: Arc<Budget>,
}

impl<S> Limited<S> {
    pub fn new(surface: S, budget: &Self) -> Self {
        Self {
            surface,
            budget: budget.budget.clone(),
        }
    }
    pub fn first(surface: S) -> Self {
        Self {
            surface,
            budget: Arc::new(Budget {
                remaining: AtomicUsize::new(MAX_MODEL_SAMPLES),
                deadline: Instant::now() + Duration::from_secs(3),
            }),
        }
    }
    fn spend(&self) {
        let old = self
            .budget
            .remaining
            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |n| n.checked_sub(1));
        if old.is_err() || old.is_ok_and(|n| n % 256 == 0 && Instant::now() > self.budget.deadline)
        {
            std::panic::resume_unwind(Box::new(SurfaceLimit));
        }
    }
}

impl<S: ParametricSurface3D> ParametricSurface for Limited<S> {
    type Point = Point3;
    type Vector = Vector3;
    fn subs(&self, u: f64, v: f64) -> Point3 {
        self.spend();
        let p = self.surface.subs(u, v);
        if !p.x.is_finite() || !p.y.is_finite() || !p.z.is_finite() {
            std::panic::resume_unwind(Box::new(SurfaceLimit));
        }
        p
    }
    fn uder(&self, u: f64, v: f64) -> Vector3 {
        self.spend();
        self.surface.uder(u, v)
    }
    fn vder(&self, u: f64, v: f64) -> Vector3 {
        self.spend();
        self.surface.vder(u, v)
    }
    fn uuder(&self, u: f64, v: f64) -> Vector3 {
        self.spend();
        self.surface.uuder(u, v)
    }
    fn uvder(&self, u: f64, v: f64) -> Vector3 {
        self.spend();
        self.surface.uvder(u, v)
    }
    fn vvder(&self, u: f64, v: f64) -> Vector3 {
        self.spend();
        self.surface.vvder(u, v)
    }
    fn parameter_range(&self) -> (ParameterRange, ParameterRange) {
        self.surface.parameter_range()
    }
    fn u_period(&self) -> Option<f64> {
        self.surface.u_period()
    }
    fn v_period(&self) -> Option<f64> {
        self.surface.v_period()
    }
}
impl<S: ParametricSurface3D> ParametricSurface3D for Limited<S> {}

impl<S: ParametricSurface3D> Limited<S> {
    fn axis(&self, range: (f64, f64), cross: (f64, f64), transpose: bool, tol: f64) -> Vec<f64> {
        if ![range.0, range.1, cross.0, cross.1, tol]
            .iter()
            .all(|v| v.is_finite())
            || tol <= 0.
        {
            std::panic::resume_unwind(Box::new(SurfaceLimit));
        }
        let sample = |t, s| {
            if transpose {
                self.subs(s, t)
            } else {
                self.subs(t, s)
            }
        };
        let mut values = vec![range.0];
        let mut pending = vec![(range.0, range.1, 0)];
        while let Some((a, b, depth)) = pending.pop() {
            let mid = a * 0.5 + b * 0.5;
            let mut flat = true;
            for fraction in [0., 0.25, 0.5, 0.75, 1.] {
                let s = cross.0 * (1. - fraction) + cross.1 * fraction;
                let (p, q) = (sample(a, s), sample(b, s));
                for fraction in [0.25, 0.5, 0.75] {
                    let t = a * (1. - fraction) + b * fraction;
                    if sample(t, s).distance2(p + (q - p) * fraction) > tol * tol {
                        flat = false;
                    }
                }
            }
            if flat {
                values.push(b);
            } else {
                if depth >= 16 || mid == a || mid == b {
                    std::panic::resume_unwind(Box::new(SurfaceLimit));
                }
                pending.push((mid, b, depth + 1));
                pending.push((a, mid, depth + 1));
            }
        }
        values
    }
}
impl<S: ParametricSurface3D> ParameterDivision2D for Limited<S> {
    fn parameter_division(
        &self,
        range: ((f64, f64), (f64, f64)),
        tol: f64,
    ) -> (Vec<f64>, Vec<f64>) {
        let u = self.axis(range.0, range.1, false, tol);
        let v = self.axis(range.1, range.0, true, tol);
        if u.len().saturating_mul(v.len()) > 16_384 {
            std::panic::resume_unwind(Box::new(SurfaceLimit));
        }
        (u, v)
    }
}
impl<S: SearchParameter<D2, Point = Point3>> SearchParameter<D2> for Limited<S> {
    type Point = Point3;
    fn search_parameter<H: Into<SPHint2D>>(
        &self,
        point: Point3,
        hint: H,
        trials: usize,
    ) -> Option<(f64, f64)> {
        self.spend();
        self.surface.search_parameter(point, hint, trials.min(100))
    }
}
impl<S: SearchNearestParameter<D2, Point = Point3>> SearchNearestParameter<D2> for Limited<S> {
    type Point = Point3;
    fn search_nearest_parameter<H: Into<SPHint2D>>(
        &self,
        point: Point3,
        hint: H,
        trials: usize,
    ) -> Option<(f64, f64)> {
        self.spend();
        self.surface
            .search_nearest_parameter(point, hint, trials.min(100))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[derive(Clone)]
    struct Parabola(f64);
    impl ParametricSurface for Parabola {
        type Point = Point3;
        type Vector = Vector3;
        fn subs(&self, u: f64, v: f64) -> Point3 {
            Point3::new(u, v, self.0 * u * u)
        }
        fn uder(&self, u: f64, _: f64) -> Vector3 {
            Vector3::new(1., 0., 2. * self.0 * u)
        }
        fn vder(&self, _: f64, _: f64) -> Vector3 {
            Vector3::new(0., 1., 0.)
        }
        fn uuder(&self, _: f64, _: f64) -> Vector3 {
            Vector3::new(0., 0., 2. * self.0)
        }
        fn uvder(&self, _: f64, _: f64) -> Vector3 {
            Vector3::new(0., 0., 0.)
        }
        fn vvder(&self, _: f64, _: f64) -> Vector3 {
            Vector3::new(0., 0., 0.)
        }
    }
    impl ParametricSurface3D for Parabola {}

    fn limited(action: impl FnOnce() + std::panic::UnwindSafe) {
        assert!(
            std::panic::catch_unwind(action)
                .unwrap_err()
                .is::<SurfaceLimit>()
        );
    }
    #[test]
    fn surface_grid_keeps_planar_faces_and_resolves_curvature_to_tolerance() {
        let flat = Limited::first(Parabola(0.));
        assert_eq!(
            flat.parameter_division(((0., 1.), (0., 1.)), 0.02),
            (vec![0., 1.], vec![0., 1.])
        );
        let curved = Limited::first(Parabola(4.));
        let (u, v) = curved.parameter_division(((0., 1.), (0., 1.)), 0.02);
        assert!(u.len() > 2);
        assert_eq!(v, vec![0., 1.]);
        for pair in u.windows(2) {
            let a = curved.subs(pair[0], 0.5);
            let b = curved.subs(pair[1], 0.5);
            for k in 1..100 {
                let t = k as f64 / 100.;
                let actual = curved.subs(pair[0] * (1. - t) + pair[1] * t, 0.5);
                assert!(actual.distance(a + (b - a) * t) <= 0.02);
            }
        }
    }
    #[test]
    fn internal_trimming_pcurve_cannot_bypass_shared_surface_budget() {
        // Invoke the same Truck PCurve subdivision used to close trimming loops.
        // Its internal recursion must unwind before uncontrolled point allocation.
        use truck_stepio::r#in::alias::re_exports::{Line, PCurve};
        let surface = Limited::first(Parabola(1e12));
        let other = Limited::new(Parabola(0.), &surface);
        surface.budget.remaining.store(512, Ordering::Relaxed);
        let curve = PCurve::new(Line(Point2::new(0., 0.), Point2::new(1., 1.)), surface);
        limited(|| {
            curve.parameter_division((0., 1.), 0.02);
        });
        assert_eq!(other.budget.remaining.load(Ordering::Relaxed), 0);
        limited(|| {
            other.subs(0., 0.);
        });
    }
    #[test]
    fn non_finite_non_converging_and_expired_surface_work_is_rejected() {
        for magnitude in [f64::NAN, f64::INFINITY, 1e100] {
            limited(|| {
                Limited::first(Parabola(magnitude)).parameter_division(((0., 1.), (0., 1.)), 0.02);
            });
        }
        let mut surface = Limited::first(Parabola(0.));
        Arc::get_mut(&mut surface.budget).unwrap().deadline =
            Instant::now() - Duration::from_secs(1);
        surface.budget.remaining.store(256, Ordering::Relaxed);
        limited(|| {
            surface.subs(0., 0.);
        });
    }
}
